-- sandhyavandanam #23.instruction_ta
update public.pooja_steps set instruction_ta = replace(instruction_ta, 'நூல் இங்கு சூர்ய நமஸ்காரத்தின் பத்து நிலைகளைக் கூறுகிறது; ஒவ்வொரு நிலையின் தொடக்கத்தில் மூச்சை இழுத்து, முடிவில் வெளியிடவும். இவற்றை யோகாசிரியரிடம் கற்பது நல்லது என்று நூலே கூறுகிறது.', 'இங்கு சூர்ய நமஸ்காரத்தின் பத்து நிலைகளைச் செய்யவும்; ஒவ்வொரு நிலையின் தொடக்கத்தில் மூச்சை இழுத்து, முடிவில் வெளியிடவும்: நிமிர்ந்து நின்று, முழங்கைகள் மார்பு உயரத்தில்; கூப்பிய கைகளை முழங்கை நேராகத் தலைக்கு மேல் உயர்த்தவும்; முழங்கால் வளையாமல் முன்குனிந்து இரு உள்ளங்கைகளையும் தரையில் வைக்கவும்; இரு கால்களையும் பின்னால் நீட்டி, முழங்கால்களை உயர்த்தி, கால்விரல்களில் நிற்கவும்; இடுப்புக்கு மேல் நிமிர்ந்து தலையை உயர்த்தவும், கைகள் உள்ளங்கைகளில் நேராக; முழங்கைகளை மடக்கித் தரையில் படுக்கவும்; இரு கைகளையும் கோத்துத் தரையில் முன்னே நீட்டவும். பின் மூன்றாம், இரண்டாம், முதல் நிலைகள் வழியாகத் திரும்பினால் ஒரு நமஸ்காரம் நிறைவு.'), updated_at = now()
 where pooja_id = 'sandhyavandanam' and step_number = 23 and position('நூல் இங்கு சூர்ய நமஸ்காரத்தின் பத்து நிலைகளைக் கூறுகிறது; ஒவ்வொரு நிலையின் தொடக்கத்தில் மூச்சை இழுத்து, முடிவில் வெளியிடவும். இவற்றை யோகாசிரியரிடம் கற்பது நல்லது என்று நூலே கூறுகிறது.' in instruction_ta) > 0;

